        // ==================== DUPLICATE DETECTION (B7) ====================
        const DuplicateChecker = {
            findDuplicates(newFAQ) {
                const duplicates = [];
                const threshold = 0.6; // 60% similarity

                State.faqList.forEach(faq => {
                    if (State.editingFAQId && faq.id === State.editingFAQId) return;

                    // Check title similarity
                    const titleSimilarity = this.calculateSimilarity(
                        newFAQ.tieuDe.toLowerCase(),
                        faq.tieuDe.toLowerCase()
                    );

                    // Check keywords overlap
                    const keywordOverlap = this.checkKeywordOverlap(
                        newFAQ.tuKhoaChinh,
                        faq.tuKhoaChinh
                    );

                    if (titleSimilarity > threshold || keywordOverlap > threshold) {
                        duplicates.push({
                            faq,
                            titleSimilarity: Math.round(titleSimilarity * 100),
                            keywordOverlap: Math.round(keywordOverlap * 100)
                        });
                    }
                });

                return duplicates;
            },

            calculateSimilarity(str1, str2) {
                if (!str1 || !str2) return 0;

                const words1 = str1.split(/\s+/);
                const words2 = str2.split(/\s+/);
                const set1 = new Set(words1);
                const set2 = new Set(words2);

                const intersection = [...set1].filter(x => set2.has(x));
                const union = new Set([...set1, ...set2]);

                return intersection.length / union.size;
            },

            checkKeywordOverlap(kw1, kw2) {
                if (!kw1 || !kw2) return 0;

                const keywords1 = kw1.toLowerCase().split(/[,\s]+/).filter(k => k.length > 2);
                const keywords2 = kw2.toLowerCase().split(/[,\s]+/).filter(k => k.length > 2);

                if (keywords1.length === 0 || keywords2.length === 0) return 0;

                const set1 = new Set(keywords1);
                const set2 = new Set(keywords2);

                const intersection = [...set1].filter(x => set2.has(x));

                return intersection.length / Math.min(set1.size, set2.size);
            }
        };

