            restore(trashId) {
                const index = State.trash.findIndex(t => t.id === trashId);
                if (index === -1) return false;

                const item = State.trash[index];
                delete item._deletedAt;
                delete item._type;
                delete item._originalId;

                // Restore to original list
                State.faqList.push(item);
                Storage.set(CONFIG.STORAGE_KEYS.FAQ, State.faqList);

                // Remove from trash
                State.trash.splice(index, 1);
                Storage.set(CONFIG.STORAGE_KEYS.TRASH, State.trash);

                this.updateBadge();
                return true;
            },

            permanentDelete(trashId) {
                const index = State.trash.findIndex(t => t.id === trashId);
                if (index !== -1) {
                    State.trash.splice(index, 1);
                    Storage.set(CONFIG.STORAGE_KEYS.TRASH, State.trash);
                    this.updateBadge();
                }
            },

            emptyTrash() {
                State.trash = [];
                Storage.set(CONFIG.STORAGE_KEYS.TRASH, State.trash);
                this.updateBadge();
            },

            cleanExpired() {
                const cutoff = Date.now() - (CONFIG.TRASH_DAYS * 24 * 60 * 60 * 1000);
                const before = State.trash.length;

                State.trash = State.trash.filter(item => item._deletedAt > cutoff);

                if (State.trash.length !== before) {
                    Storage.set(CONFIG.STORAGE_KEYS.TRASH, State.trash);
                    this.updateBadge();
                }
            },

            getDaysRemaining(deletedAt) {
                const elapsed = Date.now() - deletedAt;
                const remaining = CONFIG.TRASH_DAYS - Math.floor(elapsed / (24 * 60 * 60 * 1000));
                return Math.max(0, remaining);
            },

            updateBadge() {
                const badge = document.getElementById('trashBadge');
                if (badge) {
                    badge.textContent = State.trash.length;
                    badge.style.display = State.trash.length > 0 ? 'inline' : 'none';
                }
            }
