        // ==================== SESSION & AUTH ====================
        function checkSession() {
            const session = Storage.get(CONFIG.STORAGE_KEYS.SESSION);

            if (session) {
                const maxAge = session.remember
                    ? CONFIG.REMEMBER_DAYS * 24 * 60 * 60 * 1000
                    : 24 * 60 * 60 * 1000;

                if (Date.now() - session.timestamp < maxAge) {
                    State.currentUser = session;
                    showMainApp();
                    return;
                }
            }

            document.getElementById('loginOverlay').classList.remove('hidden');
        }

        async function handleLogin(event) {
            event.preventDefault();

            const username = document.getElementById('loginUsername').value.trim().toLowerCase();
            const password = document.getElementById('loginPassword').value;
            const remember = document.getElementById('rememberMe').checked;

            const user = State.users[username];

            if (user) {
                const inputHash = await sha256(password);

                if (inputHash === user.passwordHash) {
                    State.currentUser = {
                        username,
                        role: user.role,
                        name: user.name,
                        timestamp: Date.now(),
                        remember
                    };

                    Storage.set(CONFIG.STORAGE_KEYS.SESSION, State.currentUser);
                    document.getElementById('loginError').classList.remove('show');
                    showMainApp();
                    return;
                }
            }

            document.getElementById('loginError').classList.add('show');
        }

        function showMainApp() {
            document.getElementById('loginOverlay').classList.add('hidden');
            document.getElementById('mainApp').style.display = 'block';

            // Update header
            document.getElementById('currentUser').textContent = State.currentUser.name;

            const roleBadge = document.getElementById('userRoleBadge');
            roleBadge.textContent = State.currentUser.role.charAt(0).toUpperCase() + State.currentUser.role.slice(1);
            roleBadge.className = 'role-badge ' + State.currentUser.role;

            // Apply permissions
            applyPermissions();

            // Initialize app
            initializeApp();
        }

        function logout() {
            Storage.remove(CONFIG.STORAGE_KEYS.SESSION);
            location.reload();
        }

        function applyPermissions() {
            const role = State.currentUser.role;

            // Settings tab - admin only
            if (role !== 'admin') {
                document.getElementById('settingsTab').style.display = 'none';
            }

            // Import/Clear buttons
            if (role === 'user') {
                document.getElementById('importBtn').disabled = true;
                document.getElementById('clearAllBtn').disabled = true;
            }

            if (role !== 'admin') {
                document.getElementById('clearAllBtn').disabled = true;
            }
        }

        function canEdit(faq) {
            const role = State.currentUser.role;
            if (role === 'admin' || role === 'manager') return true;
            if (role === 'user' && faq.trangThai !== 'Đã duyệt') return true;
            return false;
        }

        function canDelete() {
            return State.currentUser.role === 'admin' || State.currentUser.role === 'manager';
        }

        function canApprove() {
            return State.currentUser.role === 'admin' || State.currentUser.role === 'manager';
        }

        // ==================== APP INITIALIZATION ====================
        function initializeApp() {
            // Setup UI
            initCategories();
            initFilters();
            initEmojiPicker();

            // Load data displays
            State.filteredFAQ = [...State.faqList];
            displayFAQPage();
            displayTemplates();
            displaySituations();
            updateStats();
            initManageFilters();
            updateDataTable();
            updateUserTable();
            updateTrashList();
            updateCalendar();
            updateAnalyticsDisplay();
            loadBackupHistory();
            updateCopyHistoryPanel();

            // Setup autosave
            updateAutosave();

            // Setup keyboard shortcuts
            setupKeyboardShortcuts();

            // Setup search debounce
            setupSearchDebounce();

            // Update footer
            updateFooterStats();

            // Undo/Redo buttons
            UndoRedo.updateButtons();

            // Trash badge
            TrashManager.updateBadge();
        }

        function initCategories() {
            // Populate group select
            const groupSelect = document.getElementById('nhomFAQ');
            groupSelect.innerHTML = '<option value="">-- Chọn nhóm --</option>';
            State.categories.groups.forEach(group => {
                groupSelect.innerHTML += `<option value="${group}">${group}</option>`;
            });

            // Populate subject checkboxes
            const subjectContainer = document.getElementById('monHocCheckboxes');
            subjectContainer.innerHTML = State.categories.subjects.map(subject => `
                <label class="checkbox-item">
                    <input type="checkbox" name="monHoc" value="${subject}"> ${subject}
                </label>
            `).join('');

            // Update settings page category lists
            updateCategoryLists();

            // Update hashtag group select
            const hashtagSelect = document.getElementById('hashtagGroup');
            if (hashtagSelect) {
                hashtagSelect.innerHTML = '<option value="">-- Chọn nhóm --</option>';
                State.categories.groups.forEach(group => {
                    hashtagSelect.innerHTML += `<option value="${group}">${group}</option>`;
                });
            }
        }

        function initFilters() {
            const groupFilters = document.getElementById('groupFilters');
            let html = '<button class="filter-btn active" onclick="filterByGroup(event, \'all\')">Tất cả</button>';

            State.categories.groups.forEach(group => {
                const count = State.faqList.filter(f => f.nhomFAQ === group).length;
                html += `<button class="filter-btn" onclick="filterByGroup(event, '${group}')">${group} (${count})</button>`;
            });

            groupFilters.innerHTML = html;
        }

