            const emojis = ['😊', '😄', '🎉', '👍', '❤️', '💪', '🌟', '✨', '🎯', '📚', '✅', '📝', '💡', '🔥', '👶', '👨‍👩‍👧', '📞', '💬', '🙏', '💜', '💙', '💚', '🧒', '👋', '🌸', '🌷', '⭐', '🏆', '♟️', '🎨'];

            const picker = document.getElementById('emojiPicker');
            picker.innerHTML = `
                <div class="emoji-grid">
                    ${emojis.map(e => `<span class="emoji-item" onclick="insertEmoji('${e}')">${e}</span>`).join('')}
                </div>
            `;
