        function editFAQ(id) {
            const faq = State.faqList.find(f => f.id === id);
            if (!faq) return;

            if (!canEdit(faq)) {
                showToast('❌ Không có quyền chỉnh sửa!', 'error');
                return;
            }

            State.editingFAQId = id;
            populateForm(faq);
            closeModal('faqDetailModal');
            switchTab({ target: document.querySelector('[data-tab="form"]') }, 'form');
            showToast('📝 Đang chỉnh sửa FAQ #' + id, 'info');
        }

        function populateForm(faq) {
            document.getElementById('loaiCauHoi').value = faq.loaiCauHoi || '';
            document.getElementById('nhomFAQ').value = faq.nhomFAQ || '';
            document.getElementById('tags').value = faq.tags || '';
            document.getElementById('tieuDe').value = faq.tieuDe || '';
            document.getElementById('cauHoiGoc').value = faq.cauHoiGoc || '';
            document.getElementById('tuKhoaChinh').value = faq.tuKhoaChinh || '';
            document.getElementById('tuKhoaMoRong').value = faq.tuKhoaMoRong || '';
            document.getElementById('noiDungTraLoi').innerText = faq.noiDungTraLoi || '';
            document.getElementById('ctaMacDinh').value = faq.ctaMacDinh || '';
            document.getElementById('ctaVariantA').value = faq.ctaVariantA || '';
            document.getElementById('ctaVariantB').value = faq.ctaVariantB || '';
            document.getElementById('ctaVariantC').value = faq.ctaVariantC || '';
            document.getElementById('fileURL').value = faq.fileURL || '';
            document.getElementById('fileURLNote').value = faq.fileURLNote || '';
            document.getElementById('doTuoi').value = faq.doTuoi || 'Tất cả';
            document.getElementById('uuTien').value = faq.uuTien || 50;
            document.getElementById('trangThai').value = faq.trangThai || 'Chờ duyệt';
            document.getElementById('ghiChuNoiBo').value = faq.ghiChuNoiBo || '';

            // Set checkboxes
            document.querySelectorAll('input[name="monHoc"]').forEach(cb => {
                cb.checked = faq.monHocLienQuan && faq.monHocLienQuan.includes(cb.value);
            });
        }

        function duplicateFAQ(id) {
            const faq = State.faqList.find(f => f.id === id);
            if (!faq) return;

            UndoRedo.saveState('faq', State.faqList);

            const newFAQ = {
                ...faq,
                id: generateId(),
                maCauHoi: generateCode(faq.loaiCauHoi, faq.nhomFAQ),
                tieuDe: faq.tieuDe + ' (Bản sao)',
                ngayTao: new Date().toISOString(),
                ngayCapNhat: new Date().toISOString(),
                nguoiTao: State.currentUser.username,
                trangThai: 'Chờ duyệt'
            };

            State.faqList.push(newFAQ);
            Storage.set(CONFIG.STORAGE_KEYS.FAQ, State.faqList);
            refreshFAQDisplay();
            showToast('📋 Đã tạo bản sao!', 'success');
        }

        function deleteFAQ(id) {
            if (!canDelete()) {
                showToast('❌ Không có quyền xóa!', 'error');
                return;
            }

            if (!confirm('Xóa FAQ này? (Có thể khôi phục từ thùng rác)')) return;

            UndoRedo.saveState('faq', State.faqList);

            const index = State.faqList.findIndex(f => f.id === id);
            if (index !== -1) {
                TrashManager.moveToTrash(State.faqList[index]);
                State.faqList.splice(index, 1);
                Storage.set(CONFIG.STORAGE_KEYS.FAQ, State.faqList);

                // Clean up references
                State.favorites = State.favorites.filter(f => f !== id);
                State.recent = State.recent.filter(f => f !== id);
                Storage.set(CONFIG.STORAGE_KEYS.FAVORITES, State.favorites);
                Storage.set(CONFIG.STORAGE_KEYS.RECENT, State.recent);

                closeModal('faqDetailModal');
                refreshFAQDisplay();
                showToast('🗑️ Đã chuyển vào thùng rác!', 'success');
            }
        }

