        // ==================== AUTOSAVE ====================
        function updateAutosave() {
            const interval = parseInt(document.getElementById('autosaveInterval').value);
            const status = document.getElementById('autosaveStatus');

            if (State.autosaveTimer) clearInterval(State.autosaveTimer);

            if (interval > 0) {
                State.autosaveTimer = setInterval(saveDraft, interval * 1000);
                status.className = 'backup-status active';
                status.innerHTML = `<span class="status-dot active"></span><span>Mỗi ${interval}s</span>`;
            } else {
                status.className = 'backup-status inactive';
                status.innerHTML = '<span class="status-dot inactive"></span><span>Tắt</span>';
            }
        }

