        // ==================== CALENDAR (D1, D4) ====================
        function updateCalendar() {
            const title = document.getElementById('calendarTitle');
            const months = ['Tháng 1', 'Tháng 2', 'Tháng 3', 'Tháng 4', 'Tháng 5', 'Tháng 6',
                'Tháng 7', 'Tháng 8', 'Tháng 9', 'Tháng 10', 'Tháng 11', 'Tháng 12'];
            title.textContent = `${months[State.currentMonth]}, ${State.currentYear}`;

            renderCalendarDays();
            renderUpcomingEvents();
        }

        function changeMonth(delta) {
            State.currentMonth += delta;
            if (State.currentMonth > 11) {
                State.currentMonth = 0;
                State.currentYear++;
            } else if (State.currentMonth < 0) {
                State.currentMonth = 11;
                State.currentYear--;
            }
            updateCalendar();
        }

        function renderCalendarDays() {
            const container = document.getElementById('calendarDays');
            const firstDay = new Date(State.currentYear, State.currentMonth, 1).getDay();
            const daysInMonth = new Date(State.currentYear, State.currentMonth + 1, 0).getDate();
            const today = new Date();

            let html = '';

            // Previous month days
            const prevMonthDays = new Date(State.currentYear, State.currentMonth, 0).getDate();
            for (let i = firstDay - 1; i >= 0; i--) {
                html += `<div class="calendar-day other-month"><span class="day-number">${prevMonthDays - i}</span></div>`;
            }

            // Current month days
            for (let day = 1; day <= daysInMonth; day++) {
                const date = new Date(State.currentYear, State.currentMonth, day);
                const dateStr = date.toISOString().split('T')[0];
                const isToday = date.toDateString() === today.toDateString();
                const events = State.calendarEvents.filter(e => e.date === dateStr);

                html += `
                    <div class="calendar-day ${isToday ? 'today' : ''}" onclick="selectCalendarDay('${dateStr}')">
                        <span class="day-number">${day}</span>
                        <div class="day-events">
                            ${events.slice(0, 3).map(e => `
                                <div class="day-event ${e.status}" onclick="event.stopPropagation(); editEvent(${e.id})">
                                    ${escapeHtml(e.title.substring(0, 15))}${e.title.length > 15 ? '...' : ''}
                                </div>
                            `).join('')}
                            ${events.length > 3 ? `<div class="day-event" style="background: var(--gray);">+${events.length - 3} more</div>` : ''}
                        </div>
                    </div>
                `;
            }

            // Next month days
            const totalCells = firstDay + daysInMonth;
            const remainingCells = totalCells % 7 === 0 ? 0 : 7 - (totalCells % 7);
            for (let i = 1; i <= remainingCells; i++) {
                html += `<div class="calendar-day other-month"><span class="day-number">${i}</span></div>`;
            }

            container.innerHTML = html;
        }

        function renderUpcomingEvents() {
            const container = document.getElementById('upcomingEvents');
            const today = new Date().toISOString().split('T')[0];

            const upcoming = State.calendarEvents
                .filter(e => e.date >= today)
                .sort((a, b) => a.date.localeCompare(b.date))
                .slice(0, 5);

            if (upcoming.length === 0) {
                container.innerHTML = '<p style="text-align: center; color: var(--text-muted); padding: 20px;">Không có sự kiện sắp tới</p>';
                return;
            }

            container.innerHTML = upcoming.map(e => `
                <div class="trash-item" style="border-left-color: ${e.status === 'published' ? 'var(--success)' : e.status === 'scheduled' ? 'var(--warning)' : 'var(--gray)'};">
                    <div class="trash-item-info">
                        <h4>${escapeHtml(e.title)}</h4>
                        <p>📅 ${new Date(e.date).toLocaleDateString('vi-VN')} ${e.time || ''} | ${e.platforms?.join(', ') || 'N/A'}</p>
                    </div>
                    <div class="trash-item-actions">
                        <button class="btn btn-sm btn-info" onclick="editEvent(${e.id})">✏️</button>
                        <button class="btn btn-sm btn-danger" onclick="deleteEvent(${e.id})">🗑️</button>
                    </div>
                </div>
            `).join('');
        }

