        function editEvent(id) {
            const event = State.calendarEvents.find(e => e.id === id);
            if (!event) return;

            State.editingEventId = id;
            document.getElementById('eventModalTitle').textContent = '✏️ Chỉnh Sửa Lịch';
            document.getElementById('eventTitle').value = event.title;
            document.getElementById('eventDate').value = event.date;
            document.getElementById('eventTime').value = event.time || '';
            document.getElementById('eventStatus').value = event.status;
            document.getElementById('eventNote').value = event.note || '';

            // Set platforms
            document.querySelectorAll('input[name="eventPlatform"]').forEach(cb => {
                cb.checked = event.platforms?.includes(cb.value);
            });

            // Set FAQ
            const faqSelect = document.getElementById('eventFAQ');
            faqSelect.innerHTML = '<option value="">-- Không liên kết --</option>' +
                State.faqList.map(f => `<option value="${f.id}" ${f.id == event.faqId ? 'selected' : ''}>${escapeHtml(f.tieuDe)}</option>`).join('');

            openModal('eventModal');
        }

        function saveEvent(event) {
            event.preventDefault();

            const platforms = Array.from(document.querySelectorAll('input[name="eventPlatform"]:checked')).map(cb => cb.value);

            const data = {
                title: document.getElementById('eventTitle').value,
                date: document.getElementById('eventDate').value,
                time: document.getElementById('eventTime').value,
                platforms,
                status: document.getElementById('eventStatus').value,
                faqId: document.getElementById('eventFAQ').value || null,
                note: document.getElementById('eventNote').value
            };

            if (State.editingEventId) {
                const index = State.calendarEvents.findIndex(e => e.id === State.editingEventId);
                if (index !== -1) {
                    State.calendarEvents[index] = { ...State.calendarEvents[index], ...data };
                }
                showToast('✅ Đã cập nhật lịch!', 'success');
            } else {
                data.id = Date.now();
                data.createdAt = new Date().toISOString();
                State.calendarEvents.push(data);
                showToast('✅ Đã thêm lịch mới!', 'success');
            }

            Storage.set(CONFIG.STORAGE_KEYS.CALENDAR, State.calendarEvents);
            updateCalendar();
            closeModal('eventModal');
        }

        function deleteEvent(id) {
            if (!confirm('Xóa lịch này?')) return;
            State.calendarEvents = State.calendarEvents.filter(e => e.id !== id);
            Storage.set(CONFIG.STORAGE_KEYS.CALENDAR, State.calendarEvents);
            updateCalendar();
            showToast('🗑️ Đã xóa lịch!', 'success');
        }

        function exportCalendar() {
            const data = State.calendarEvents.map(e => ({
                'Tiêu đề': e.title,
                'Ngày': e.date,
                'Giờ': e.time,
                'Nền tảng': e.platforms?.join(', '),
                'Trạng thái': e.status,
                'Ghi chú': e.note
            }));

            const ws = XLSX.utils.json_to_sheet(data);
            const wb = XLSX.utils.book_new();
            XLSX.utils.book_append_sheet(wb, ws, 'Calendar');
            XLSX.writeFile(wb, `SkillUp_Calendar_${formatDateForFile(new Date())}.xlsx`);
            showToast('📊 Đã xuất lịch!', 'success');
        }

        // ==================== ANALYTICS (C1) ====================
        function updateAnalyticsDisplay() {
            const days = parseInt(document.getElementById('analyticsRange')?.value) || 30;
            const stats = Analytics.getStats(days === 'all' ? 99999 : days);

            // Update stats
            document.getElementById('totalCopyStat').textContent = stats.totalCopies;
            document.getElementById('topFAQCopyStat').textContent = stats.topFAQs[0]?.count || 0;
            document.getElementById('avgCopyStat').textContent = stats.avgPerFAQ;
            document.getElementById('platformStat').textContent = stats.topPlatform;

            // Platform chart
            renderPlatformChart(stats.byPlatform);

            // Daily chart
            renderDailyChart(stats.byDay);

            // Top FAQs list
            renderTopFAQsList(stats.topFAQs);

            // CTA performance
            renderCTAPerformance(stats.byCTA);
        }

        function renderPlatformChart(data) {
            const container = document.getElementById('platformChart');
            const platforms = ['facebook', 'zalo', 'instagram', 'tiktok', 'twitter', 'linkedin', 'direct'];
            const maxValue = Math.max(...Object.values(data), 1);

            container.innerHTML = platforms.map(p => {
                const value = data[p] || 0;
                const height = (value / maxValue) * 150;
                return `
                    <div class="chart-bar" style="height: ${Math.max(height, 20)}px;" title="${p}: ${value}">
                        <span class="chart-bar-value">${value}</span>
                        <span class="chart-bar-label">${p.substring(0, 2).toUpperCase()}</span>
                    </div>
                `;
            }).join('');
        }

        function renderDailyChart(data) {
            const container = document.getElementById('dailyChart');
            const entries = Object.entries(data).slice(-7);
            const maxValue = Math.max(...entries.map(e => e[1]), 1);

            if (entries.length === 0) {
                container.innerHTML = '<p style="text-align: center; color: var(--text-muted);">Chưa có dữ liệu</p>';
                return;
            }

            container.innerHTML = entries.map(([day, value]) => {
                const height = (value / maxValue) * 150;
                const shortDay = day.split('/').slice(0, 2).join('/');
                return `
                    <div class="chart-bar" style="height: ${Math.max(height, 20)}px;" title="${day}: ${value}">
                        <span class="chart-bar-value">${value}</span>
                        <span class="chart-bar-label">${shortDay}</span>
                    </div>
                `;
            }).join('');
        }

        function renderTopFAQsList(data) {
            const container = document.getElementById('topFAQsList');

            if (data.length === 0) {
                container.innerHTML = '<p style="text-align: center; color: var(--text-muted);">Chưa có dữ liệu</p>';
                return;
            }

            container.innerHTML = data.map((item, i) => `
                <div class="analytics-list-item">
                    <span class="analytics-list-item-label">${i + 1}. ${escapeHtml(item.title.substring(0, 40))}${item.title.length > 40 ? '...' : ''}</span>
                    <span class="analytics-list-item-value">${item.count}</span>
                </div>
            `).join('');
        }

        function renderCTAPerformance(data) {
            const container = document.getElementById('ctaPerformanceList');
            const entries = Object.entries(data).sort((a, b) => b[1] - a[1]);

            if (entries.length === 0) {
                container.innerHTML = '<p style="text-align: center; color: var(--text-muted);">Chưa có dữ liệu</p>';
                return;
            }

            const labels = {
                'answer': 'Trả lời',
                'cta': 'CTA Mặc định',
                'ctaA': 'CTA A',
                'ctaB': 'CTA B',
                'ctaC': 'CTA C',
                'full': 'Đầy đủ'
            };

            container.innerHTML = entries.map(([type, count]) => `
                <div class="analytics-list-item">
                    <span class="analytics-list-item-label">${labels[type] || type}</span>
                    <span class="analytics-list-item-value">${count}</span>
                </div>
            `).join('');
        }

        function exportAnalytics() {
            const stats = Analytics.getStats(99999);

            const data = {
                exportDate: new Date().toISOString(),
                totalCopies: stats.totalCopies,
                byPlatform: stats.byPlatform,
                topFAQs: stats.topFAQs,
                byCTA: stats.byCTA
            };

            downloadFile(JSON.stringify(data, null, 2), `SkillUp_Analytics_${formatDateForFile(new Date())}.json`, 'application/json');
            showToast('📊 Đã xuất báo cáo!', 'success');
        }

        // ==================== TRASH ====================
        function updateTrashList() {
            const container = document.getElementById('trashList');

            if (State.trash.length === 0) {
                container.innerHTML = '<p style="text-align: center; color: var(--text-muted); padding: 40px;">🎉 Thùng rác trống!</p>';
                return;
            }

            container.innerHTML = State.trash.map(item => {
                const daysRemaining = TrashManager.getDaysRemaining(item._deletedAt);
                return `
                    <div class="trash-item">
                        <div class="trash-item-info">
                            <h4>${escapeHtml(item.tieuDe || item.name || 'Không có tiêu đề')}</h4>
                            <p>🆔 ${item.maCauHoi || item.id} | Xóa: ${new Date(item._deletedAt).toLocaleDateString('vi-VN')}</p>
                            <p class="trash-countdown">⏱️ Còn ${daysRemaining} ngày trước khi xóa vĩnh viễn</p>
                        </div>
                        <div class="trash-item-actions">
                            <button class="btn btn-sm btn-success" onclick="restoreFromTrash(${item.id})">🔄 Khôi phục</button>
                            <button class="btn btn-sm btn-danger" onclick="permanentDeleteFromTrash(${item.id})">🗑️ Xóa vĩnh viễn</button>
                        </div>
                    </div>
                `;
            }).join('');
        }

        function restoreFromTrash(id) {
            if (TrashManager.restore(id)) {
                refreshFAQDisplay();
                updateTrashList();
                showToast('🔄 Đã khôi phục!', 'success');
            }
        }

        function permanentDeleteFromTrash(id) {
            if (!confirm('Xóa vĩnh viễn? Không thể hoàn tác!')) return;
            TrashManager.permanentDelete(id);
            updateTrashList();
            showToast('🗑️ Đã xóa vĩnh viễn!', 'success');
        }

        function restoreAllTrash() {
            if (!confirm(`Khôi phục tất cả ${State.trash.length} mục?`)) return;

            State.trash.forEach(item => {
                delete item._deletedAt;
                delete item._type;
                delete item._originalId;
                State.faqList.push(item);
            });

            Storage.set(CONFIG.STORAGE_KEYS.FAQ, State.faqList);
            TrashManager.emptyTrash();
            refreshFAQDisplay();
            updateTrashList();
            showToast('🔄 Đã khôi phục tất cả!', 'success');
        }

        function emptyTrash() {
            if (!confirm('Xóa vĩnh viễn tất cả? Không thể hoàn tác!')) return;
            TrashManager.emptyTrash();
            updateTrashList();
            showToast('🗑️ Đã dọn sạch thùng rác!', 'success');
        }

        // ==================== BACKUP ====================
        function updateAutoBackup() {
            const interval = document.getElementById('autoBackupInterval').value;
            const status = document.getElementById('autoBackupStatus');

            if (State.autoBackupTimer) clearInterval(State.autoBackupTimer);

            if (interval !== '0') {
                const ms = interval === 'hourly' ? 3600000 : interval === 'daily' ? 86400000 : 604800000;
                State.autoBackupTimer = setInterval(createBackup, ms);
                status.className = 'backup-status active';
                status.innerHTML = '<span class="status-dot active"></span><span>Đang hoạt động</span>';
            } else {
                status.className = 'backup-status inactive';
                status.innerHTML = '<span class="status-dot inactive"></span><span>Tắt</span>';
            }
        }

        function createBackup() {
            const backup = {
                version: CONFIG.VERSION,
                date: new Date().toISOString(),
                exportedBy: State.currentUser?.username || 'system',
                faq: State.faqList,
                templates: State.templates,
                situations: State.situations,
                categories: State.categories,
                hashtags: State.hashtags,
                calendarEvents: State.calendarEvents,
                analytics: State.analytics
            };

            // Save to backup history
            const backupMeta = Storage.get(CONFIG.STORAGE_KEYS.BACKUPS) || [];
            backupMeta.unshift({
                id: Date.now(),
                date: backup.date,
                faqCount: State.faqList.length,
                by: backup.exportedBy
            });

            if (backupMeta.length > 10) backupMeta.splice(10);
            Storage.set(CONFIG.STORAGE_KEYS.BACKUPS, backupMeta);

            downloadFile(JSON.stringify(backup, null, 2), `SkillUp_Backup_${formatDateForFile(new Date())}.json`, 'application/json');
            loadBackupHistory();
            showToast('💾 Đã tạo backup!', 'success');
        }

        function downloadLatestBackup() {
            createBackup();
        }

        function loadBackupHistory() {
            const backups = Storage.get(CONFIG.STORAGE_KEYS.BACKUPS) || [];
            const container = document.getElementById('backupList');

            if (backups.length === 0) {
                container.innerHTML = '<p style="text-align: center; color: var(--text-muted); padding: 40px;">Chưa có backup nào</p>';
                return;
            }

            container.innerHTML = backups.map(b => `
                <div class="backup-item">
                    <div class="backup-item-info">
                        <div class="backup-item-icon">💾</div>
                        <div class="backup-item-details">
                            <h4>${new Date(b.date).toLocaleString('vi-VN')}</h4>
                            <p>${b.faqCount} FAQ | Bởi: ${b.by}</p>
                        </div>
                    </div>
                    <button class="btn btn-sm btn-outline" onclick="alert('Backup đã được lưu vào thư mục Downloads')">Tải lại</button>
                </div>
            `).join('');
        }

        function showRestoreModal() {
            if (State.currentUser.role === 'user') {
                showToast('❌ Không có quyền!', 'error');
                return;
            }
            openModal('restoreModal');
        }

        function processRestore() {
            const file = document.getElementById('restoreFile').files[0];
            if (!file) {
                showToast('❌ Chưa chọn file!', 'error');
                return;
            }

            const reader = new FileReader();
            reader.onload = function (e) {
                try {
                    const data = JSON.parse(e.target.result);

                    if (data.faq) {
                        State.faqList = data.faq;
                        Storage.set(CONFIG.STORAGE_KEYS.FAQ, State.faqList);
                    }
                    if (data.templates) {
                        State.templates = data.templates;
                        Storage.set(CONFIG.STORAGE_KEYS.TEMPLATES, State.templates);
                    }
                    if (data.situations) {
                        State.situations = data.situations;
                        Storage.set(CONFIG.STORAGE_KEYS.SITUATIONS, State.situations);
                    }
                    if (data.categories) {
                        State.categories = data.categories;
                        Storage.set(CONFIG.STORAGE_KEYS.CATEGORIES, State.categories);
                    }
                    if (data.hashtags) {
                        State.hashtags = data.hashtags;
                        Storage.set(CONFIG.STORAGE_KEYS.HASHTAGS, State.hashtags);
                    }
                    if (data.calendarEvents) {
                        State.calendarEvents = data.calendarEvents;
                        Storage.set(CONFIG.STORAGE_KEYS.CALENDAR, State.calendarEvents);
                    }

                    closeModal('restoreModal');
                    initializeApp();
                    showToast('🔄 Khôi phục thành công!', 'success');
                } catch (err) {
                    showToast('❌ File không hợp lệ: ' + err.message, 'error');
                }
            };
            reader.readAsText(file);
        }

